function energy(L, I){ return 0.5*L*I*I; } // J, energy stored in inductor
function reactance(L, f){ return 2*Math.PI*f*L; } // Ω, inductive reactance
function timeConstant(L, R){ if(!(R>0)) return NaN; return L/R; } // s, RL circuit
var EXPORTS = { energy:energy, reactance:reactance, timeConstant:timeConstant };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.InductanceForgePure = EXPORTS; }
